import{_ as t,o,c as s,a5 as e}from"./chunks/framework.Cct9zD0Q.js";const r="/RBQ/nightly/images/software/simulator-architecture.ko.svg",i="/RBQ/nightly/images/software/rl-pipeline.ko.svg",p=JSON.parse('{"title":"RBQ 시뮬레이터","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/simulator/overview.md","filePath":"ko/software/simulator/overview.md","lastUpdated":1795599730000}'),l={name:"ko/software/simulator/overview.md"};function n(c,a,d,m,h,u){return o(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="rbq-시뮬레이터" tabindex="-1">RBQ 시뮬레이터 <a class="header-anchor" href="#rbq-시뮬레이터" aria-label="Permalink to &quot;RBQ 시뮬레이터&quot;">​</a></h1><p>RBQ 오픈소스 패키지에는 <strong>목적이 다른</strong> 두 종류의 시뮬레이터가 포함되어 있습니다:</p><ul><li><strong>오픈소스 물리 시뮬레이터</strong> — <a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo</a>, <a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo</a>, <a href="/RBQ/nightly/ko/software/simulator/isaac-sim.html">Isaac Sim</a>은 시뮬레이션 위에서 <strong>RBQ 소프트웨어 스택 전체</strong>를 실행하여, 하드웨어 없이 로봇 소프트웨어를 개발·검증할 수 있게 합니다.</li><li><strong>강화학습 학습 환경</strong> — <a href="/RBQ/nightly/ko/software/simulator/rbq-gym.html">Isaac Gym</a>과 <a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab</a>은 보행 정책을 <strong>학습</strong>하고 실제 로봇에 <strong>배포</strong>할 수 있게 합니다.</li></ul><h2 id="시뮬레이터" tabindex="-1">시뮬레이터 <a class="header-anchor" href="#시뮬레이터" aria-label="Permalink to &quot;시뮬레이터&quot;">​</a></h2><table tabindex="0"><thead><tr><th>시뮬레이터</th><th>엔진</th><th>패키지 경로</th><th>목적</th></tr></thead><tbody><tr><td><strong>MuJoCo</strong></td><td>MuJoCo</td><td><code>rbq_simulator/rbq_mujoco/</code></td><td>RBQ 스택 전체를 시뮬레이션에서 실행</td></tr><tr><td><strong>Gazebo</strong></td><td>Ignition Gazebo (Fortress)</td><td><code>rbq_simulator/rbq_gazebo/</code></td><td>RBQ 스택 전체를 시뮬레이션에서 실행</td></tr><tr><td><strong>Isaac Sim</strong></td><td>Isaac Sim 5.1</td><td><code>rbq_simulator/rbq_sim/</code></td><td>RBQ 스택 전체를 시뮬레이션에서 실행</td></tr><tr><td><strong>Isaac Gym</strong></td><td>IsaacGym (Preview 4)</td><td><code>rbq_simulator/rbq_gym/</code></td><td>강화학습 — 빠른 병렬 학습</td></tr><tr><td><strong>Isaac Lab</strong></td><td>Isaac Sim / Isaac Lab</td><td><code>rbq_simulator/rbq_lab/</code></td><td>강화학습 — 고정밀 시뮬레이션</td></tr></tbody></table><p>MuJoCo와 Gazebo는 로봇 변형 두 가지를 지원합니다 — RBQ (사족, 기본)와 RBQW (휠타입, <code>--wheel</code>, 다리 12관절 + 구동륜 4개). <code>scripts/sim.bash -r wheel</code> 로 RBQ 스택에도 같은 변형을 전달해야 Motion 이 휠까지 구동합니다. Isaac Sim은 사족만 있습니다.</p><p>라이다는 MuJoCo, Gazebo, Isaac Sim 모두 같은 플래그로 옵트인입니다 — <code>--livox</code> (Livox Mid-360 x2, 앞 / 뒤) 또는 <code>--ouster</code> (Ouster OS1 x1, 뒤 데크). 플래그가 없으면 라이다는 달리지 않습니다. MuJoCo의 <code>--ouster</code> 는 하우징만 그립니다.</p><h2 id="동작-구조-mujoco-gazebo-isaac-sim" tabindex="-1">동작 구조 (MuJoCo / Gazebo / Isaac Sim) <a class="header-anchor" href="#동작-구조-mujoco-gazebo-isaac-sim" aria-label="Permalink to &quot;동작 구조 (MuJoCo / Gazebo / Isaac Sim)&quot;">​</a></h2><img src="'+r+'" alt="시뮬레이터와 RBQ 소프트웨어 스택" style="width:100%;"><ul><li>시뮬레이터와 RBQ 소프트웨어 스택은 같은 PC에서 <strong>DDS</strong>(도메인 0, 루프백)로 통신합니다. 로봇 소프트웨어는 실기와 똑같이 고치지 않고 그대로 돕니다.</li><li>시뮬레이터는 로봇 상태(관절, IMU, 접촉), 카메라 영상, LiDAR 점군을 보내고, RBQ 소프트웨어 스택은 관절 지령을 돌려보냅니다.</li><li>로봇은 웹 UI(<code>http://127.0.0.1:8080</code>)에서 조종하고, ROS 2 노드는 로봇 토픽을 바로 읽습니다.</li></ul><p>실행 방법은 각 페이지에 있습니다: <a href="/RBQ/nightly/ko/software/simulator/mujoco.html#run">MuJoCo</a>, <a href="/RBQ/nightly/ko/software/simulator/gazebo.html#run">Gazebo</a>, <a href="/RBQ/nightly/ko/software/simulator/isaac-sim.html#run">Isaac Sim</a>.</p><h2 id="정책-학습-배포-isaac-gym-isaac-lab" tabindex="-1">정책 학습 &amp; 배포 (Isaac Gym / Isaac Lab) <a class="header-anchor" href="#정책-학습-배포-isaac-gym-isaac-lab" aria-label="Permalink to &quot;정책 학습 &amp; 배포 (Isaac Gym / Isaac Lab)&quot;">​</a></h2><p>강화학습 환경은 동일한 <strong>Train → Play → Deploy</strong> 파이프라인을 따릅니다:</p><img src="'+i+`" alt="Train → Play → Sim2Sim → Deploy" style="width:100%;"><p>학습 완료 후 <code>policy.onnx</code>와 <code>info.json</code>을 <code>rbq_low_level</code>에 로드해 로봇에서 실행합니다.</p><h2 id="저장소-구조" tabindex="-1">저장소 구조 <a class="header-anchor" href="#저장소-구조" aria-label="Permalink to &quot;저장소 구조&quot;">​</a></h2><p>시뮬레이터 코드는 <code>rbq_simulator/</code> 아래에 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RBQ/</span></span>
<span class="line"><span>└── rbq_simulator/</span></span>
<span class="line"><span>    ├── rbq_mujoco/        # MuJoCo 시뮬레이터 (스택 전체)</span></span>
<span class="line"><span>    ├── rbq_gazebo/        # Ignition Gazebo 시뮬레이터 (스택 전체 + ROS 2 브리지)</span></span>
<span class="line"><span>    ├── rbq_sim/           # Isaac Sim 시뮬레이터 (스택 전체)</span></span>
<span class="line"><span>    ├── rbq_gym/           # Isaac Gym 강화학습 환경</span></span>
<span class="line"><span>    └── rbq_lab/           # Isaac Lab 강화학습 환경</span></span></code></pre></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo →</a> — MuJoCo에서 스택 전체 실행</li><li><a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo →</a> — Gazebo에서 스택 전체 실행</li><li><a href="/RBQ/nightly/ko/software/simulator/isaac-sim.html">Isaac Sim →</a> — Isaac Sim에서 스택 전체 실행</li><li><a href="/RBQ/nightly/ko/software/simulator/rbq-gym.html">Isaac Gym →</a> — Isaac Gym 학습 가이드</li><li><a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab →</a> — Isaac Lab 학습 가이드</li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/low-level.html">Low Level (RL 정책) →</a> — 학습된 정책을 실제 로봇에 배포</li></ul>`,20)])])}const g=t(l,[["render",n]]);export{p as __pageData,g as default};
